@Override public void getPaymentAccounts(GetPaymentAccountsRequest req, StreamObserver<GetPaymentAccountsReply> responseObserver) {
  try {
    var paymentAccounts = coreApi.getPaymentAccounts().stream()
        .map(PaymentAccount::toProtoMessage)
        .collect(Collectors.toList());
    var reply = GetPaymentAccountsReply.newBuilder()
        .addAllPaymentAccounts(paymentAccounts)
        .build();
    responseObserver.onNext(reply);
    responseObserver.onCompleted();
  } catch (RuntimeException e) {
    responseObserver.onError(Status.INTERNAL
        .withDescription("Failed to process payment accounts")
        .withCause(e)
        .asRuntimeException());
  }
}
